          "Katrina A. Hovey",
          "Anne C. Ittner"
        ],
        "openAccessInfo": {
          "license": "CCBYNC",
          "status": "GOLD",
          "disclaimer": "Notice: This snippet is extracted from the open access paper or abstract available at https://api.unpaywall.org/v2/10.30958/aje.10-1-5?email=<INSERT_YOUR_EMAIL> or https://doi.org/10.30958/aje.10-1-5, which is subject to the license by the author or copyright owner provided with this content. Please go to the source to verify the license and copyright information for your use."
        }
